import { z } from 'zod';

export const GUIDANCE_REFERENCE_COUNT = 32;
export const GUIDANCE_REFERENCE_FILE_COUNT = 100;
export const GUIDANCE_REFERENCE_FILE_BYTES = 1024 * 1024;
export const GUIDANCE_REFERENCE_TOTAL_BYTES = 5 * 1024 * 1024;
const REFERENCE_NAME_LENGTH = 500;
const REFERENCE_INTENT_LENGTH = 10000;
const REFERENCE_URL_LENGTH = 2048;
const REFERENCE_PATH_LENGTH = 4096;
const REFERENCE_SEGMENT_BYTES = 255;
const FIRST_PRINTABLE_CODE_POINT = 32;
const DELETE_CODE_POINT = 127;
const isUtf8Text = (text: string): boolean =>
  new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(
    new TextEncoder().encode(text),
  ) === text;

export const GuidanceReferenceNameSchema = z
  .string()
  .min(1)
  .max(REFERENCE_NAME_LENGTH)
  .refine(
    (name) =>
      isUtf8Text(name) &&
      !/[\\:<>"|?*]/.test(name) &&
      [...name].every(
        (character) =>
          character.charCodeAt(0) >= FIRST_PRINTABLE_CODE_POINT &&
          character.charCodeAt(0) !== DELETE_CODE_POINT,
      ) &&
      name
        .split('/')
        .every(
          (part) =>
            part !== '' &&
            part !== '.' &&
            part !== '..' &&
            new TextEncoder().encode(part).byteLength <=
              REFERENCE_SEGMENT_BYTES &&
            !/[. ]$/.test(part) &&
            !/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(part),
        ),
    'Reference file names must be safe relative paths without traversal',
  );
export const GuidanceReferenceFileUploadSchema = z
  .object({
    name: GuidanceReferenceNameSchema,
    content: z
      .string()
      .refine(
        (content) =>
          !content.includes('\0') &&
          new TextEncoder().encode(content).byteLength <=
            GUIDANCE_REFERENCE_FILE_BYTES &&
          isUtf8Text(content),
        'Reference files must be valid UTF-8 text without NUL bytes, at most 1 MiB',
      ),
  })
  .strict();
const DigestSchema = z.string().regex(/^[a-f0-9]{64}$/);
const GuidanceReferenceFileSchema = GuidanceReferenceFileUploadSchema.extend({
  path: z.string().min(1).optional(),
  sha256: DigestSchema.optional(),
});
const ReferenceIntentSchema = z
  .string()
  .trim()
  .min(1)
  .max(REFERENCE_INTENT_LENGTH);
export const GuidanceDirectoryPathSchema = z
  .string()
  .min(1)
  .max(REFERENCE_PATH_LENGTH)
  .refine(
    (value) => isUtf8Text(value) && !value.includes('\0'),
    'Directory paths must be valid UTF-8 without NUL bytes',
  );
export const GuidanceDirectoryReferenceSchema = z
  .object({
    kind: z.literal('directory'),
    path: GuidanceDirectoryPathSchema.refine(
      (value) =>
        value.startsWith('/') ||
        /^[a-z]:[\\/]/i.test(value) ||
        /^\\\\[^\\/]+[\\/][^\\/]+/.test(value),
      'Directory references require an absolute path',
    ),
    intent: ReferenceIntentSchema,
  })
  .strict();
const ReferenceOriginSchema = z
  .object({
    kind: z.enum(['url', 'repository']),
    url: z
      .string()
      .url()
      .max(REFERENCE_URL_LENGTH)
      .refine((value) => {
        if (!URL.canParse(value)) return false;
        const url = new URL(value);
        return (
          ['https:', 'http:'].includes(url.protocol) &&
          !url.username &&
          !url.password
        );
      }, 'References require HTTP(S) URLs without credentials'),
    intent: ReferenceIntentSchema,
    revision: z.string().trim().min(1).max(REFERENCE_NAME_LENGTH).optional(),
  })
  .strict();

export const GuidanceRemoteReferenceUploadSchema = ReferenceOriginSchema.extend(
  {
    files: z
      .array(GuidanceReferenceFileUploadSchema)
      .max(GUIDANCE_REFERENCE_FILE_COUNT)
      .optional(),
  },
);
const GuidanceRemoteReferenceSchema = ReferenceOriginSchema.extend({
  files: z
    .array(GuidanceReferenceFileSchema)
    .max(GUIDANCE_REFERENCE_FILE_COUNT)
    .optional(),
  digest: DigestSchema.optional(),
});
export const GuidanceReferenceUploadSchema = z.discriminatedUnion('kind', [
  GuidanceRemoteReferenceUploadSchema,
  GuidanceDirectoryReferenceSchema,
]);
const GuidanceReferenceSchema = z.discriminatedUnion('kind', [
  GuidanceRemoteReferenceSchema,
  GuidanceDirectoryReferenceSchema,
]);
export type GuidanceReference = z.infer<typeof GuidanceReferenceSchema>;
export type GuidanceReferenceUpload = z.infer<
  typeof GuidanceReferenceUploadSchema
>;

export const GuidanceFilesSchema = z
  .array(GuidanceReferenceFileUploadSchema)
  .min(1)
  .max(GUIDANCE_REFERENCE_FILE_COUNT)
  .superRefine((files, context) => {
    if (
      files.reduce(
        (bytes, file) =>
          bytes + new TextEncoder().encode(file.content).byteLength,
        0,
      ) > GUIDANCE_REFERENCE_TOTAL_BYTES
    )
      context.addIssue({
        code: 'custom',
        message: 'Retained files exceed the 5 MiB text limit',
      });
    const directories = new Map<string, string>();
    for (const file of files) {
      const segments = file.name.split('/');
      for (let length = 1; length < segments.length; length++) {
        const directory = segments.slice(0, length).join('/');
        const key = directory.normalize('NFC').toLowerCase();
        const existing = directories.get(key);
        if (existing !== undefined && existing !== directory)
          context.addIssue({
            code: 'custom',
            path: [],
            message:
              'Reference directories must use consistent spelling and casing',
          });
        directories.set(key, directory);
      }
    }
    const names = files
      .map((file) => file.name.normalize('NFC').toLowerCase())
      .sort();
    names.forEach((name, position) => {
      if (
        names
          .slice(0, position)
          .some(
            (previous) => name === previous || name.startsWith(`${previous}/`),
          )
      )
        context.addIssue({
          code: 'custom',
          path: [],
          message:
            'Reference file names must not duplicate or contain another file path',
        });
    });
  });

const validateReferences = (
  references: GuidanceReferenceUpload[],
  context: z.RefinementCtx,
): void => {
  const files = references.flatMap((reference) =>
    reference.kind === 'directory' ? [] : (reference.files ?? []),
  );
  if (files.length > GUIDANCE_REFERENCE_FILE_COUNT)
    context.addIssue({
      code: 'custom',
      message: 'Saved references exceed the 100-file limit',
    });
  if (
    files.reduce(
      (bytes, file) =>
        bytes + new TextEncoder().encode(file.content).byteLength,
      0,
    ) > GUIDANCE_REFERENCE_TOTAL_BYTES
  )
    context.addIssue({
      code: 'custom',
      message: 'Saved references exceed the 5 MiB text limit',
    });
  references.forEach((reference, index) => {
    if (reference.kind === 'directory') return;
    const parsed = GuidanceFilesSchema.safeParse(
      (reference.files ?? []).map(({ name, content }) => ({ name, content })),
    );
    if (reference.files?.length && !parsed.success)
      parsed.error.issues.forEach((issue) =>
        context.addIssue({ ...issue, path: [index, 'files', ...issue.path] }),
      );
  });
};

export const GuidanceReferencesUploadSchema = z
  .array(GuidanceReferenceUploadSchema)
  .max(GUIDANCE_REFERENCE_COUNT)
  .superRefine(validateReferences);
export const GuidanceReferencesSchema = z
  .array(GuidanceReferenceSchema)
  .max(GUIDANCE_REFERENCE_COUNT)
  .superRefine(validateReferences);
